    function money(value,plus=false){const n=finite(value,NaN);if(!Number.isFinite(n))return '—';const sign=n<0?'−':plus&&n>0?'+':'';return `${sign}${new Intl.NumberFormat('fr-FR',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Math.abs(n))} USD`}
