    const SHOTS_META_KEY = 'nexus.shots.meta.v1';
    const SHOTS_DB_NAME = 'nexus.shots.v1';
    let shotsMeta = [];
    let shotOpenId = null;
    let shotUrls = {};
    function loadShotsMeta(){try{const raw=JSON.parse(localStorage.getItem(SHOTS_META_KEY)||'[]');shotsMeta=Array.isArray(raw)?raw:[]}catch{shotsMeta=[]}}
    function persistShotsMeta(){localStorage.setItem(SHOTS_META_KEY, JSON.stringify(shotsMeta))}
    function openShotsDb(){return new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(new Error('IndexedDB indisponible'));const req=indexedDB.open(SHOTS_DB_NAME,1);req.onupgradeneeded=()=>{req.result.createObjectStore('blobs')};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
    function shotsPut(id, record){return openShotsDb().then(db=>new Promise((resolve,reject)=>{const tx=db.transaction('blobs','readwrite');tx.objectStore('blobs').put(record,id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)}))}
    function shotsGet(id){return openShotsDb().then(db=>new Promise((resolve,reject)=>{const tx=db.transaction('blobs','readonly');const r=tx.objectStore('blobs').get(id);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error)}))}
    function shotsDel(id){return openShotsDb().then(db=>new Promise((resolve,reject)=>{const tx=db.transaction('blobs','readwrite');tx.objectStore('blobs').delete(id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)}))}
    function revokeShotUrls(){Object.values(shotUrls).forEach(u=>{try{URL.revokeObjectURL(u)}catch(_){}});shotUrls={}}
    function compressToJpeg(file, maxSide, quality){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file);const img=new Image();img.onload=()=>{const scale=Math.min(1, maxSide/Math.max(img.width,img.height));const w=Math.max(1,Math.round(img.width*scale));const h=Math.max(1,Math.round(img.height*scale));const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);c.toBlob(blob=>{URL.revokeObjectURL(url);if(!blob)return reject(new Error('compress'));resolve({blob,w,h})},'image/jpeg',quality)};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('image'))};img.src=url})}
    async function ingestShotFiles(files, extra={}){
      const list=[...files].filter(f=>f && /^image\//.test(f.type));
      if(!list.length){toast('Aucune image valide.','error');return []}
      const added=[];
      for(const file of list.slice(0,16)){
        if(file.size>18000000){toast(file.name+' trop lourd (max 18 Mo).','error');continue}
        try{
          const full=await compressToJpeg(file, 1920, 0.84);
          const thumb=await compressToJpeg(file, 480, 0.72);
          const rec={id:id('shot'), name:file.name||'capture', createdAt:Date.now(), date:extra.date||todayISO(), title:(extra.title||file.name||'Capture').replace(/\.[a-z0-9]+$/i,''), market:extra.market||'ALL', setupId:extra.setupId||'', tradeId:extra.tradeId||'', note:extra.note||'', w:full.w, h:full.h, bytes:full.blob.size};
          await shotsPut(rec.id, {full:full.blob, thumb:thumb.blob, mime:'image/jpeg'});
          shotsMeta.unshift(rec);
          added.push(rec);
        }catch(err){toast('Import impossible : '+file.name,'error')}
      }
      if(added.length){persistShotsMeta();renderShots();toast(added.length+' capture'+(added.length>1?'s':'')+' enregistrée'+(added.length>1?'s':'.') )}
      return added;
    }
    function filteredShots(){
      const q=(refs.shotSearch.value||'').trim().toLowerCase();
      const m=refs.shotFilterMarket.value, s=refs.shotFilterSetup.value, l=refs.shotFilterLink.value;
      return shotsMeta.filter(sh=>{
        if(m!=='ALL' && sh.market!==m && sh.market!=='ALL') return false;
        if(s!=='ALL' && sh.setupId!==s) return false;
        if(l==='linked' && !sh.tradeId) return false;
        if(l==='free' && sh.tradeId) return false;
        if(!q) return true;
        const hay=[sh.title,sh.note,sh.name,sh.market,setupName(sh.setupId)].join(' ').toLowerCase();
        return hay.includes(q);
      });
    }
    function setupName(id){const s=state.setups.find(x=>x.id===id);return s?s.name:''}
    function fillShotSelects(){
      const fill=(el, first)=>{if(!el)return;const cur=el.value;el.innerHTML=first;MARKETS.forEach(m=>{const o=document.createElement('option');o.value=m;o.textContent=m;el.appendChild(o)});el.value=cur||'ALL'}
      fill(refs.shotFilterMarket, '<option value="ALL">Tous</option>');
      fill(refs.shotMarket, '<option value="ALL">—</option>');
      const fillSetup=(el, first)=>{if(!el)return;const cur=el.value;el.innerHTML=first;state.setups.forEach(s=>{const o=document.createElement('option');o.value=s.id;o.textContent=s.name;el.appendChild(o)});el.value=cur||'ALL'}
      fillSetup(refs.shotFilterSetup, '<option value="ALL">Tous</option>');
      fillSetup(refs.shotSetup, '<option value="">—</option>');
      if(refs.shotTrade){const cur=refs.shotTrade.value;refs.shotTrade.innerHTML='<option value="">— aucun —</option>';reverseChron(state.trades).slice(0,80).forEach(tr=>{const o=document.createElement('option');o.value=tr.id;o.textContent=`${dateFormat(tr.date)} · ${tr.instrument} · ${money(tr.pnl,true)}`;refs.shotTrade.appendChild(o)});refs.shotTrade.value=cur||''}
    }
    async function renderShots(){
      if(!refs.shotGrid)return;
      fillShotSelects();
      const items=filteredShots();
      refs.shotStatus.textContent = shotsMeta.length ? `${items.length} / ${shotsMeta.length} capture${shotsMeta.length>1?'s':''} · stockage local` : 'Aucune capture pour le moment.';
      revokeShotUrls();
      while(refs.shotGrid.firstChild) refs.shotGrid.removeChild(refs.shotGrid.firstChild);
      if(!items.length){const empty=document.createElement('div');empty.className='shot-empty';empty.textContent=shotsMeta.length?'Aucun résultat pour ce filtre.':'Importez votre première capture de chart.';refs.shotGrid.appendChild(empty);return}
      for(const sh of items){
        const fig=document.createElement('figure');fig.className='shot-card';fig.dataset.shot=sh.id;
        const img=document.createElement('img');img.alt=sh.title||'Capture';
        const cap=document.createElement('figcaption');
        const b=document.createElement('b');b.textContent=sh.title||'Sans titre';
        const i=document.createElement('i');i.textContent=`${sh.date||''} · ${sh.market&&sh.market!=='ALL'?sh.market:'—'} · ${sh.w}×${sh.h}`;
        cap.appendChild(b);cap.appendChild(i);fig.appendChild(img);fig.appendChild(cap);refs.shotGrid.appendChild(fig);
        try{const rec=await shotsGet(sh.id); if(rec&&rec.thumb){const u=URL.createObjectURL(rec.thumb);shotUrls[sh.id]=u;img.src=u}}catch(_){}
      }
    }
    async function openShot(id){
      const sh=shotsMeta.find(x=>x.id===id); if(!sh)return;
      shotOpenId=id; fillShotSelects();
      refs.shotTitle.value=sh.title||''; refs.shotDate.value=sh.date||todayISO();
      refs.shotMarket.value=sh.market||'ALL'; refs.shotSetup.value=sh.setupId||'';
      refs.shotTrade.value=sh.tradeId||''; refs.shotNote.value=sh.note||'';
      refs.shotLight.hidden=false; refs.shotLight.classList.add('open');
      refs.shotLightImg.removeAttribute('src');
      try{const rec=await shotsGet(id); if(rec&&rec.full){const u=URL.createObjectURL(rec.full);shotUrls['full-'+id]=u;refs.shotLightImg.src=u}}catch(_){}
    }
    function closeShot(){refs.shotLight.classList.remove('open');refs.shotLight.hidden=true;shotOpenId=null}
    function setupShotsUi(){
      loadShotsMeta();
      const pick=()=>refs.shotFile.click();
      refs.shotPick.addEventListener('click', pick);
      refs.shotDrop.addEventListener('click', pick);
      refs.shotDrop.addEventListener('keydown', e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick()}});
      refs.shotFile.addEventListener('change', async()=>{await ingestShotFiles(refs.shotFile.files);refs.shotFile.value=''});
      ['dragenter','dragover'].forEach(ev=>refs.shotDrop.addEventListener(ev,e=>{e.preventDefault();refs.shotDrop.classList.add('over')}));
      ['dragleave','drop'].forEach(ev=>refs.shotDrop.addEventListener(ev,e=>{e.preventDefault();refs.shotDrop.classList.remove('over')}));
      refs.shotDrop.addEventListener('drop', e=>{const files=e.dataTransfer&&e.dataTransfer.files; if(files) ingestShotFiles(files)});
      refs.shotSearch.addEventListener('input', ()=>renderShots());
      refs.shotFilterMarket.addEventListener('change', ()=>renderShots());
      refs.shotFilterSetup.addEventListener('change', ()=>renderShots());
      refs.shotFilterLink.addEventListener('change', ()=>renderShots());
      refs.shotGrid.addEventListener('click', e=>{const card=e.target.closest('[data-shot]'); if(card) openShot(card.dataset.shot)});
      refs.shotLightClose.addEventListener('click', closeShot);
      refs.shotLight.addEventListener('click', e=>{if(e.target===refs.shotLight) closeShot()});
      document.addEventListener('keydown', e=>{if(e.key==='Escape' && refs.shotLight.classList.contains('open')) closeShot()});
      document.addEventListener('paste', e=>{
        if(document.documentElement.getAttribute('data-page')!=='shots') return;
        const files=[...((e.clipboardData&&e.clipboardData.files)||[])];
        if(files.length){e.preventDefault();ingestShotFiles(files)}
      });
      refs.shotSaveMeta.addEventListener('click', ()=>{
        const sh=shotsMeta.find(x=>x.id===shotOpenId); if(!sh)return;
        sh.title=refs.shotTitle.value.trim()||sh.title;
        sh.date=refs.shotDate.value||sh.date;
        sh.market=refs.shotMarket.value||'ALL';
        sh.setupId=refs.shotSetup.value||'';
        sh.tradeId=refs.shotTrade.value||'';
        sh.note=refs.shotNote.value.trim();
        persistShotsMeta(); renderShots(); toast('Fiche capture enregistrée.');
      });
      refs.shotDownload.addEventListener('click', async()=>{
        if(!shotOpenId)return;
        try{const rec=await shotsGet(shotOpenId); if(!rec||!rec.full)return; const a=document.createElement('a'); a.href=URL.createObjectURL(rec.full); a.download=(shotsMeta.find(x=>x.id===shotOpenId)||{}).title||'capture.jpg'; a.click()}catch(_){toast('Téléchargement impossible.','error')}
      });
      refs.shotDelete.addEventListener('click', async()=>{
        if(!shotOpenId||!confirm('Supprimer cette capture ?'))return;
        const idDel=shotOpenId;
        shotsMeta=shotsMeta.filter(x=>x.id!==idDel);
        persistShotsMeta();
        try{await shotsDel(idDel)}catch(_){}
        closeShot(); renderShots(); toast('Capture supprimée.');
      });
      refs.shotClear.addEventListener('click', async()=>{
        if(!shotsMeta.length)return;
        if(!confirm('Effacer toute la galerie de captures ?'))return;
        const ids=shotsMeta.map(s=>s.id);
        shotsMeta=[]; persistShotsMeta();
        for(const id0 of ids){try{await shotsDel(id0)}catch(_){}}
        closeShot(); renderShots(); toast('Galerie vidée.');
      });
      if(refs.fShotFile) refs.fShotFile.addEventListener('change', async()=>{
        const f=refs.fShotFile.files&&refs.fShotFile.files[0]; if(!f)return;
        const d=draftFromForm();
        const added=await ingestShotFiles([f], {market:d.instrument, date:d.date, setupId:d.setupId, title:d.instrument+' '+d.date});
        if(added[0]){refs.fScreenshot.value='shot:'+added[0].id; state.draft=draftFromForm(); scheduleSave(); toast('Capture liée au formulaire journal.')}
        refs.fShotFile.value='';
      });
    }

    function renderAll(){syncSelects();syncDraft();syncRiskProfile();syncNews();syncChecklist();renderSession();renderMetrics();renderEquity();renderMarket();renderBreakdown();renderHeatmap();renderInsights();renderPlaybook();renderJournal();renderShots();renderReviews();renderAccounts();setSave('saved')}

    function calculateRisk(){const acc=accountById(refs.riskAccount.value),entry=finite(refs.riskEntry.value,NaN),stop=finite(refs.riskStop.value,NaN),pct=Math.max(0,finite(refs.riskPct.value,acc.riskPerTradePct)),pv=Math.max(0,finite(refs.riskPointValue.value,0)),step=Math.max(.0000001,finite(refs.riskStep.value,.01)),target=finite(refs.riskTarget.value,NaN),cash=acc.initialCapital+accountTrades(acc.id).reduce((s,t)=>s+t.pnl,0);const risk=cash*pct/100,distance=Number.isFinite(entry)&&Number.isFinite(stop)?Math.abs(entry-stop):NaN;const raw=distance>0&&pv>0?risk/(distance*pv):NaN;const volume=Number.isFinite(raw)?Math.floor(raw/step)*step:NaN;const rr=Number.isFinite(target)&&distance>0?Math.abs(target-entry)/distance:NaN;refs.riskCash.textContent=money(risk);refs.riskDistance.textContent=Number.isFinite(distance)?distance.toLocaleString('fr-FR',{maximumFractionDigits:6}):'—';refs.riskVolume.textContent=Number.isFinite(volume)&&volume>0?volume.toLocaleString('fr-FR',{maximumFractionDigits:6}):'—';refs.riskRR.textContent=Number.isFinite(rr)?`${rr.toFixed(2)} R`:'—';return {accountId:acc.id,instrument:refs.riskInstrument.value,risk,entry,stop,target,volume:Math.max(0,finite(volume,0)),rr}}
    function openTrade(trade){refs.dialogTitle.textContent=`${trade.instrument} · ${dateFormat(trade.date)}`;refs.dialogSub.textContent=`${accountName(trade.accountId)} · ${setupName(trade.setupId)} · ${trade.direction}`;while(refs.dialogContent.firstChild)refs.dialogContent.removeChild(refs.dialogContent.firstChild);const fields=[['P&L net',money(trade.pnl,true)],['R-multiple',rOf(trade)===null?'—':`${rOf(trade).toFixed(2)} R`],['Entrée / sortie',`${trade.entry||'—'} → ${trade.exit||'—'}`],['Stop / target',`${trade.stop||'—'} → ${trade.target||'—'}`],['Volume',trade.volume||'—'],['Risque cash',trade.riskUsd?money(trade.riskUsd):'—'],['Commission',money(trade.commission)],['Session',trade.session],['Plan / News',`${trade.plan} · ${trade.newsState}`],['Confiance / discipline',`${trade.confidence}/10 · ${trade.discipline}/10`],['Psychologie',`${trade.beforeEmotion} → ${trade.afterEmotion}${trade.fomo==='Oui'?' · FOMO identifié':''}`],['Capture',trade.screenshot||'—'],['Note',trade.note||'—']];fields.forEach(([key,val])=>{const cell=document.createElement('div');cell.className='detail';const k=document.createElement('div');k.className='k';k.textContent=key;const v=document.createElement('div');v.className='v';if(key==='Capture'&&trade.screenshot){const a=document.createElement('a');if(String(trade.screenshot).startsWith('shot:')){a.href='#shots';a.textContent='Voir dans Captures'}else{a.href=trade.screenshot;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Ouvrir la capture ↗'}v.appendChild(a)}else v.textContent=val;cell.append(k,v);refs.dialogContent.appendChild(cell)});if(typeof refs.tradeDialog.showModal==='function')refs.tradeDialog.showModal();else refs.tradeDialog.setAttribute('open','')}
